import SwiftUI

struct InspectorView:View{@EnvironmentObject var store:BoardStore; @State private var width=3.0;@State private var opacity=1.0;@State private var color=Color.primary;@State private var pattern=StrokePattern.solid
 var body:some View{VStack(alignment:.leading,spacing:16){HStack{Text("Inspector").font(.headline);Spacer();Text("\(store.selection.count) selected").font(.caption).foregroundStyle(.secondary)};ColorPicker("Stroke",selection:$color).onChange(of:color){_,v in let c=NSColor(v).usingColorSpace(.deviceRGB)!;store.mutate{b in for i in b.elements.indices where store.selection.contains(b.elements[i].id){b.elements[i].stroke=RGBAColor(red:c.redComponent,green:c.greenComponent,blue:c.blueComponent,alpha:c.alphaComponent)}}};LabeledContent("Width"){Slider(value:$width,in:1...32).frame(width:120)}.onChange(of:width){_,v in store.mutate{b in for i in b.elements.indices where store.selection.contains(b.elements[i].id){b.elements[i].width=v}}};LabeledContent("Opacity"){Slider(value:$opacity,in:0.05...1).frame(width:120)};Picker("Pattern",selection:$pattern){ForEach(StrokePattern.allCases,id:\.self){Text($0.rawValue.capitalized)}};Divider();HStack{Button("Group"){store.mutate{ElementEditor.group(&$0.elements,ids:store.selection)}};Button("Lock"){store.toggleLock()};Button(role:.destructive,action:store.deleteSelection){Image(systemName:"trash")}};HStack{Button("Back"){store.moveZ(false)};Button("Front"){store.moveZ(true)}}}.padding(16).background(.regularMaterial).clipShape(RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(.separator.opacity(0.4),lineWidth:0.5)).shadow(color:.black.opacity(0.1),radius:6,y:2)} }

struct SettingsView:View{@EnvironmentObject var store:BoardStore;@AppStorage("stabilizer")var stabilizer=0.45;@AppStorage("snapGrid")var snapGrid=true;@AppStorage("rulers")var rulers=false;@AppStorage("appearance")var appearance="Auto"
 var body:some View{Form{Section("Drawing"){LabeledContent("Stabilizer"){Slider(value:$stabilizer,in:0...1)};Toggle("Snap to grid",isOn:$snapGrid);Toggle("Show rulers",isOn:$rulers)};Section("Appearance"){Picker("Theme",selection:$appearance){Text("Auto").tag("Auto");Text("Light").tag("Light");Text("Dark").tag("Dark")};Picker("Background",selection:Binding(get:{store.current.background},set:{v in store.mutate{$0.background=v}})){ForEach(CanvasBackground.allCases,id:\.self){Text($0.rawValue.capitalized)}}}Section("Camera"){Text("Camera frames are processed locally and never saved or transmitted.").foregroundStyle(.secondary)}}.formStyle(.grouped).padding()}}
